package database

import (
	"database/sql"
	"fmt"
	"os"
	"regexp"
	"sort"
	"strings"
	"testing"
)

// TestGeneratePGBaseline 把 SQLite 迁移到最新之后的结构翻译成 PostgreSQL 的基线迁移,默认跳过。
//
//	LB_GEN_PG_BASELINE=internal/database/migrations_pg/0048_baseline.sql go test ./internal/database/ -run TestGeneratePGBaseline
//
// 只在建 PG 基线那一次用;生成的文件人工核对后提交,之后**不再重新生成**(迁移文件应用后不可改)。
// 以后的迁移两边各手写一份。翻译规则只有类型映射与建表顺序:
//
//   - `INTEGER PRIMARY KEY [AUTOINCREMENT]` 名为 id 的 → BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY
//     (SQLite 插入时不给 id 会自动分配,PG 要靠 identity 做到同一件事);
//   - 其余 INTEGER → BIGINT(流量是字节数),REAL → DOUBLE PRECISION;
//   - 外键在 PG 里要求被引用的表先存在,按外键依赖做拓扑排序;索引在全部表之后,视图按原顺序最后建。
func TestGeneratePGBaseline(t *testing.T) {
	out := os.Getenv("LB_GEN_PG_BASELINE")
	if out == "" {
		t.Skip("设 LB_GEN_PG_BASELINE=<输出路径> 才生成")
	}
	db := openTestDB(t)
	if err := Migrate(db, nil); err != nil {
		t.Fatal(err)
	}
	type obj struct{ typ, name, tbl, sql string }
	rows, err := db.Query(`SELECT type, name, tbl_name, COALESCE(sql, '') FROM sqlite_master
		WHERE name NOT LIKE 'sqlite_%' AND name != 'schema_migrations' ORDER BY rowid`)
	if err != nil {
		t.Fatal(err)
	}
	var tables, indexes, views []obj
	for rows.Next() {
		var o obj
		rows.Scan(&o.typ, &o.name, &o.tbl, &o.sql)
		switch o.typ {
		case "table":
			tables = append(tables, o)
		case "index":
			if o.sql != "" { // 自动索引(UNIQUE / PRIMARY KEY 约束带出来的)没有 sql,PG 会自己建
				indexes = append(indexes, o)
			}
		case "view":
			views = append(views, o)
		default:
			t.Fatalf("没处理的对象类型 %s %s", o.typ, o.name)
		}
	}
	rows.Close()

	deps := map[string][]string{}
	for _, tb := range tables {
		deps[tb.name] = foreignTables(t, db, tb.name)
	}
	order := topoSort(t, tables, deps, func(o obj) string { return o.name })

	var b strings.Builder
	b.WriteString(`-- PostgreSQL 基线:与 SQLite 迁移 0001–0048 结束时的结构等价(VNext S2)。
--
-- 由 internal/database/pgbaseline_gen_test.go 从 SQLite 的最终结构翻译生成、人工核对后提交;
-- **应用后不可修改**,以后的结构变更在 migrations/ 与 migrations_pg/ 各加一个同版本号的迁移。
-- 各张表、各列的含义见 SQLite 那一侧的迁移注释与 docs/数据库说明.md。

`)
	for _, tb := range order {
		b.WriteString(convertTable(tb.sql) + ";\n\n")
	}
	for _, ix := range indexes {
		b.WriteString(strings.TrimSpace(ix.sql) + ";\n")
	}
	b.WriteString("\n")
	for _, v := range views {
		b.WriteString(strings.TrimSpace(v.sql) + ";\n\n")
	}
	// 迁移里插进去的初始数据(内置访问等级、系统设置默认值、计数器……):迁移跑完之后表里已有的行原样带上。
	b.WriteString("-- 初始数据:SQLite 迁移 0001–0048 跑完之后表里已有的行。\n")
	for _, tb := range order {
		writeSeedRows(t, db, &b, tb.name)
	}
	if err := os.WriteFile(out, []byte(b.String()), 0o644); err != nil {
		t.Fatal(err)
	}
}

func writeSeedRows(t *testing.T, db *sql.DB, b *strings.Builder, table string) {
	rows, err := db.Query(`SELECT * FROM "` + table + `" ORDER BY 1`)
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	cols, _ := rows.Columns()
	types, _ := rows.ColumnTypes()
	n := 0
	for rows.Next() {
		vals := make([]any, len(cols))
		ptrs := make([]any, len(cols))
		for i := range vals {
			ptrs[i] = &vals[i]
		}
		if err := rows.Scan(ptrs...); err != nil {
			t.Fatal(err)
		}
		lits := make([]string, len(vals))
		for i, v := range vals {
			lits[i] = sqlLiteral(v, types[i].DatabaseTypeName())
		}
		fmt.Fprintf(b, "INSERT INTO %s (%s) VALUES (%s);\n", table, strings.Join(cols, ", "), strings.Join(lits, ", "))
		n++
	}
	if n > 0 && hasIdentity(t, db, table) {
		fmt.Fprintf(b, "SELECT setval(pg_get_serial_sequence('%s', 'id'), (SELECT MAX(id) FROM %s));\n", table, table)
	}
}

func hasIdentity(t *testing.T, db *sql.DB, table string) bool {
	var sql string
	db.QueryRow(`SELECT sql FROM sqlite_master WHERE type = 'table' AND name = ?`, table).Scan(&sql)
	return reIdentity.MatchString(sql)
}

func sqlLiteral(v any, typ string) string {
	switch x := v.(type) {
	case nil:
		return "NULL"
	case int64:
		return fmt.Sprint(x)
	case float64:
		return fmt.Sprint(x)
	case []byte:
		return "'" + strings.ReplaceAll(string(x), "'", "''") + "'"
	case string:
		return "'" + strings.ReplaceAll(x, "'", "''") + "'"
	default:
		panic(fmt.Sprintf("没处理的值类型 %T", v))
	}
}

func foreignTables(t *testing.T, db *sql.DB, table string) []string {
	rows, err := db.Query(`SELECT DISTINCT "table" FROM pragma_foreign_key_list(?)`, table)
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	var out []string
	for rows.Next() {
		var s string
		rows.Scan(&s)
		out = append(out, s)
	}
	sort.Strings(out)
	return out
}

func topoSort[T any](t *testing.T, items []T, deps map[string][]string, name func(T) string) []T {
	byName := map[string]T{}
	for _, it := range items {
		byName[name(it)] = it
	}
	var out []T
	state := map[string]int{}
	var visit func(n string)
	visit = func(n string) {
		switch state[n] {
		case 1:
			return
		case 2:
			t.Fatalf("外键成环:%s", n)
		}
		state[n] = 2
		for _, d := range deps[n] {
			if d == n {
				continue // 自引用
			}
			if _, ok := byName[d]; !ok {
				t.Fatalf("%s 引用了不存在的表 %s", n, d)
			}
			visit(d)
		}
		state[n] = 1
		out = append(out, byName[n])
	}
	for _, it := range items {
		visit(name(it))
	}
	return out
}

var (
	reIdentity = regexp.MustCompile(`(?i)\b("?id"?)\s+INTEGER\s+PRIMARY\s+KEY(\s+AUTOINCREMENT)?`)
	reInteger  = regexp.MustCompile(`(?i)\bINTEGER\b`)
	reReal     = regexp.MustCompile(`(?i)\bREAL\b`)
	reAutoinc  = regexp.MustCompile(`(?i)\s+AUTOINCREMENT\b`)
)

func convertTable(sql string) string {
	sql = strings.TrimSpace(sql)
	sql = reIdentity.ReplaceAllString(sql, "$1 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY")
	sql = reAutoinc.ReplaceAllString(sql, "")
	sql = reInteger.ReplaceAllString(sql, "BIGINT")
	sql = reReal.ReplaceAllString(sql, "DOUBLE PRECISION")
	if strings.Contains(strings.ToUpper(sql), "WITHOUT ROWID") {
		panic(fmt.Sprintf("WITHOUT ROWID 没处理:%s", sql))
	}
	return sql
}
